/* 一纸榆林 — buildless, pointer-first chapter engine. All game state stays on device. */
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const chapters=[
 {label:'序章',title:'初见一纸',sub:'一张纸，藏着一座城',story:'风从塞上来，捎来一张未展开的纸。\n请你轻轻折开，让山河有了形状。',after:'第一道纸痕里，露出了远山。\n沿着它往前走，城的故事才刚刚开始。',card:'一剪一世界',fact:'剪纸以剪刀或刻刀在纸上形成图案。折叠后剪刻再展开，可以得到对称或重复的纹样。2009年，中国剪纸列入联合国教科文组织人类非物质文化遗产代表作名录。',url:'https://ich.unesco.org/en/RL/chinese-paper-cut-00219',source:'联合国教科文组织 · 中国剪纸'},
 {label:'第一章',title:'剪出边塞',sub:'一座城的守望',story:'纸上的山脊，像一条沉睡的长城。\n剪开轮廓，让镇北台从时光里站起来。',after:'风穿过垛口，也吹过山下的集市。\n这座高台，守望过边塞，也见证过往来。',card:'镇北台 · 守望与互市',fact:'镇北台位于榆林城北红山之巅，始建于1607年，1608年建成。它是明长城的重要台体建筑，也与红山互市的历史紧密相连，见证了边塞贸易与交流。',url:'https://yl.gov.cn/mlyl/zjyl/fjms/202009/t20200928_18048.html',source:'榆林市人民政府 · 镇北台自然人文大舞台'},
 {label:'第二章',title:'剪出人家',sub:'窗花里的日子',story:'循着炊烟，来到黄土坡上的人家。\n剪一朵窗花，把日子的盼头贴上窗。',after:'窗花一贴，屋里就有了喜气。\n一剪一刻，是人们对好日子的心愿。',card:'陕北剪纸 · 把心愿贴上窗',fact:'中国剪纸常用于窗户、门、墙面等处的装饰，也参与节庆和人生礼俗。花鸟、动物与人物等题材表达生活经验和美好愿望。这里的窗花是以对称剪纸为灵感设计的互动纹样。',url:'https://ich.unesco.org/en/RL/chinese-paper-cut-00219',source:'联合国教科文组织 · 中国剪纸'},
 {label:'第三章',title:'剪出红火',sub:'一方土地的热闹',story:'院外响起鼓点，红绸在风里招手。\n剪出舞者，接上彩绸，一起扭起来。',after:'脚步踩上鼓点，彩绸把风也染暖。\n纸上的人活了，黄土地上的热闹也近了。',card:'陕北秧歌 · 扭出精气神',fact:'陕北秧歌是流传于陕北的民间歌舞，绥德是其重要传承地区之一。群体舞蹈伴随锣鼓等乐器，常见于节庆活动。游戏中的节奏与舞姿为艺术化简化设计。',url:'https://www.ihchina.cn/search_result/keyword/%E9%99%95%E5%8C%97%E7%A7%A7%E6%AD%8C',source:'中国非物质文化遗产网 · 陕北秧歌检索'},
 {label:'第四章',title:'剪出声音',sub:'一曲吹过黄土地',story:'红绸落下，一支唢呐接住了风。\n剪开喇叭口，让纸带把声音送向远山。',after:'高亢的旋律翻过山梁。\n有人吹响日常，也有人用它记住故乡。',card:'绥米唢呐 · 山梁上的回响',fact:'绥米唢呐主要流传于陕西绥德、米脂及周边地区，是民间鼓吹乐的一种。大吹多在行进中演奏，小吹多在厅堂院落围坐演奏，深深融入当地的民俗生活。',url:'https://www.ihchina.cn/project_details/12520.html',source:'中国非物质文化遗产网 · 绥米唢呐'}
];
let saved={chapter:0,completed:[],name:''};try{saved={...saved,...JSON.parse(localStorage.getItem('yizhi-yulin-v1')||'{}')};}catch{}
let state={chapter:0,phase:'intro',cut:0,folded:false,beats:0,sound:false,music:false,placed:[],pattern:0};let audio=null, timers=[], frame=0,run=0;
const save=()=>{try{localStorage.setItem('yizhi-yulin-v1',JSON.stringify(saved))}catch{}};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function clearWork(){timers.forEach(clearTimeout);timers=[];cancelAnimationFrame(frame);run++;state.music=false;if(audio)audio.suspend();}
function later(fn,ms){timers.push(setTimeout(fn,ms))}
function top(){return `<header class="topbar"><button class="round" id="home" aria-label="返回封面">‹</button><span class="brand">一纸榆林</span><div class="top-actions"><button class="round" id="sound" aria-label="${state.sound?'关闭':'开启'}音频">${state.sound?'♪':'♩'}</button><button class="round" id="map" aria-label="章节目录">☷</button></div></header>`}
function bindTop(){const h=$('#home');if(h)h.onclick=cover;$('#sound').onclick=()=>{state.sound=!state.sound;$('#sound').textContent=state.sound?'♪':'♩';$('#sound').setAttribute('aria-label',state.sound?'关闭音频':'开启音频');if(!state.sound&&audio)audio.suspend();toast(state.sound?'声音已开启 · 可点旁白朗读':'声音已关闭');if(!state.sound&&'speechSynthesis'in window)speechSynthesis.cancel()};$('#map').onclick=map;}
function cover(){clearWork();app.innerHTML=`<section class="screen cover"><div class="cover-art"></div><header class="topbar"><span class="brand">清爽榆林</span><div class="top-actions"><button class="round" id="sound" aria-label="音频开关">${state.sound?'♪':'♩'}</button><button class="round" id="map" aria-label="章节目录">☷</button></div></header><div class="cover-title"><span class="eyebrow">剪纸里的边塞长卷</span><h1>一纸榆林</h1><span class="seal">清爽榆林</span><div class="subtitle">一 剪 一 景 · 一 纸 一 城</div></div><div class="cover-bottom"><div class="poem">把山河折进纸里<br>让故事，在指尖慢慢展开</div><button class="primary" id="start">${saved.completed.length?'继续我的长卷':'展开第一张纸'}<b>→</b></button><div class="chapter-links"><button data-card="1">边塞</button><button data-card="2">人家</button><button data-card="3">红火</button><button data-card="4">声音</button></div><button class="quiet" id="guide">指尖游玩指南 ↗</button><div class="edition">YULIN · AN INTERACTIVE PAPER STORY</div></div></section>`;bindTop();$('#start').onclick=()=>enter(saved.completed.length?Math.min(saved.chapter,5):0);$('#guide').onclick=()=>show(`<span class="card-overline">HOW TO PLAY</span><h2>让纸上的故事<br>在你手里发生</h2><p>① 轻点展开，再沿圆点指示的虚线滑动剪刻。<br>② 将剪出的纸片拖到轮廓附近，松手自动贴合；也可点选纸片后点轮廓。<br>③ 等鼓点亮起时点击，让舞者跟上节拍。<br>④ 点按音符，听声音化成纸带。</p><p>每章完成后可阅读文化卡。进度自动保存在本机，随时从目录重温。音频需主动开启；旁白朗读取决于浏览器中文语音支持。</p>`);document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>card(+b.dataset.card));}
function show(html){$('#modalContent').innerHTML=html;modal.showModal()}
$('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
function card(i){const c=chapters[i];show(`<span class="card-overline">PAPER NOTES · 文化拾遗</span><h2>${c.card}</h2><p>${c.fact}</p><a href="${c.url}" target="_blank" rel="noopener">资料来源：${c.source} ↗</a><p class="small-label">场景与纹样为艺术化创作</p>`)}
function map(){show(`<span class="card-overline">YOUR PAPER JOURNEY</span><h2>纸上的行旅</h2>${[...chapters,{label:'终章',title:'展开榆林'}].map((c,i)=>`<button class="map-row" data-ch="${i}"><span>${c.label} · ${c.title}</span><small>${saved.completed.includes(i)?'已收藏 ✓':i<=saved.completed.length?'可探索 →':'待展开 ·'}</small></button>`).join('')}`);document.querySelectorAll('[data-ch]').forEach(b=>b.onclick=()=>{const i=+b.dataset.ch;if(i>saved.completed.length)return toast('先完成前面的纸上故事');modal.close();enter(i)})}
function enter(i){clearWork();if('speechSynthesis'in window)speechSynthesis.cancel();state={...state,chapter:i,phase:'intro',cut:0,folded:false,beats:0,placed:[]};saved.chapter=i;save();if(i===5)return ending();render();}
const svg=(body)=>`<svg viewBox="0 0 400 360" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="纸艺互动场景"><defs><filter id="grain"><feTurbulence type="fractalNoise" baseFrequency=".55" numOctaves="2" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".08"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter><pattern id="bricks" width="27" height="17" patternUnits="userSpaceOnUse"><path d="M0 0H27M0 17H27M13 0V8M0 8H27M0 8V17M27 8V17" fill="none" stroke="#926c4d" stroke-width=".6" opacity=".4"/></pattern></defs>${body}</svg>`;
function flower(cx=200,cy=175,size=1,color='#cc6045'){return `<g transform="translate(${cx} ${cy}) scale(${size})" fill="${color}">${Array.from({length:8},(_,i)=>`<g transform="rotate(${i*45})"><path d="M0 -12C-65 -50 -32 -100 0 -120C32 -100 65 -50 0 -12Z"/><path d="M0 -40Q-20 -65 0 -90Q20 -65 0 -40Z" fill="#f8ecd2"/><path d="M0 -102L-18 -117L0 -137L18 -117Z"/></g>`).join('')}<circle r="34"/><g fill="#f8ecd2">${Array.from({length:8},(_,i)=>`<ellipse rx="7" ry="16" transform="rotate(${i*45}) translate(0 -18)"/>`).join('')}</g><circle r="7" fill="${color}"/></g>`}
function tower(){return `<g class="paper-piece" filter="url(#grain)"><path d="M12 303L74 265L121 235L171 244L232 218L295 197L397 254V360H0Z" fill="#d6a069"/><path d="M28 319L93 276L149 267L199 294L263 252L322 265L395 247V360H0Z" fill="#bb7e51"/><path d="M40 299L100 255L153 268L225 236L266 230L326 205" fill="none" stroke="#eed5a0" stroke-width="20"/><path d="M40 287L51 280V289L67 279V270L77 263V272L93 261V252L104 249V260L121 263V252L134 255V266L153 271L170 263V252L181 249V258L204 249V238L217 235V243L238 236V226L251 224V232" fill="none" stroke="#eed5a0" stroke-width="7"/><path d="M227 233L237 139H314L330 233Z" fill="#d3a15d"/><path d="M243 139L249 99H302L309 139Z" fill="#e4b66e"/><path d="M255 100V74H297V100" fill="#c68a50"/><path d="M234 139H314M248 99H306M254 75H299" stroke="#365f51" stroke-width="8"/><path d="M232 139V128H241V139M253 139V128H263V139M278 139V128H288V139M306 139V128H316V139M252 98V87H262V98M279 98V87H290V98M253 75V65H263V75M285 75V65H296V75" fill="#345f52"/><path d="M269 233V201Q282 180 294 201V233M262 167V156Q267 149 272 156V167M289 167V156Q294 149 299 156V167M268 120V110H276V120M286 120V110H294V120" fill="#40594a"/><path d="M229 145H319V234H229Z" fill="url(#bricks)"/><path d="M10 350Q120 275 193 326T400 312V360H0Z" fill="#3d7a68"/><path d="M30 357Q108 303 150 330T310 350" fill="none" stroke="#afc2a0" stroke-width="3"/></g>`}
function cave(){return `<g class="paper-piece" filter="url(#grain)"><path d="M3 268Q45 147 126 143Q208 116 278 153Q346 139 400 233V360H0Z" fill="#cc9b68"/><path d="M31 278V211Q31 140 102 140Q174 140 174 211V278Z" fill="#efd7ae"/><path d="M192 278V207Q192 144 257 144Q322 144 322 207V278Z" fill="#f2dbb5"/><path d="M45 278V211Q45 155 102 155Q159 155 159 211V278Z" fill="#526b5b"/><path d="M207 278V207Q207 158 257 158Q307 158 307 207V278Z" fill="#577263"/><path d="M102 157V278M46 220H158M71 168V278M132 168V278M208 220H306M257 158V278M232 168V278M282 168V278" stroke="#e4bd83" stroke-width="5"/><path d="M0 280H400V360H0Z" fill="#e8c797"/><path d="M15 285H332M6 301H345M0 320H370" stroke="#d0a270" stroke-width="3"/><path d="M351 266L339 188L347 139M343 197L379 172M342 169L318 145" stroke="#395d48" stroke-width="7" fill="none"/>${Array.from({length:9},(_,i)=>`<ellipse cx="${320+(i*23)%67}" cy="${136+(i*17)%66}" rx="18" ry="9" fill="${i%2?'#518975':'#285b50'}" transform="rotate(-25 ${320+(i*23)%67} ${136+(i*17)%66})"/>`).join('')}<path d="M25 272L20 241H49L44 272" fill="#aa6447"/><path d="M34 245V214M34 232L15 215M34 222L48 203" stroke="#49735a" stroke-width="5"/></g>`}
function dancer(){return `<g id="dancer" class="paper-piece ${state.phase==='rhythm'||state.phase==='done'?'dancing':''}" filter="url(#grain)"><path d="M191 263L163 327L143 331L135 344L174 343L212 276M215 262L244 322L261 327L269 339L233 337L195 276" fill="#245557"/><path d="M181 168L146 210L104 172L96 184L147 233L193 202M219 170L250 197L281 153L295 161L256 222L210 203" fill="#d16847"/><path d="M176 164Q200 153 225 165L235 265Q204 289 165 263Z" fill="#cf6847"/><path d="M182 166L207 215L220 163L228 201L216 225L171 208" fill="#235858"/><path d="M172 232L230 237L232 248L169 242Z" fill="#e9bd75"/><path d="M184 257L224 259M183 270L221 271" stroke="#edbf80" stroke-width="3"/><ellipse cx="201" cy="136" rx="25" ry="29" fill="#eac397"/><path d="M176 137Q166 99 199 98Q234 96 229 138L218 122L199 110L179 140Z" fill="#254d48"/><circle cx="215" cy="102" r="12" fill="#cb6043"/><circle cx="229" cy="111" r="8" fill="#c75a42"/><path d="M187 138L194 136M208 136L215 139M197 151Q202 155 208 150" stroke="#405c4a" stroke-width="2" fill="none"/><path d="M177 169L166 198M226 168L236 194" stroke="#eec489" stroke-width="3"/><path d="M96 177Q34 123 40 219Q65 257 19 284M291 157Q341 97 357 167T383 220" class="ribbon"/></g>`}
function musician(){return `<g class="paper-piece" filter="url(#grain)"><path d="M146 190Q180 170 211 187L248 321Q175 346 107 316Z" fill="#25575a"/><path d="M150 195L175 236L193 183L204 204L183 251Z" fill="#ecddad"/><path d="M168 212L185 240L200 201L206 226L187 266Z" fill="#cc6848"/><path d="M153 203L197 244L238 215L244 230L197 267L132 227M198 202L224 233L258 209L269 221L224 257L191 230" fill="#337273"/><ellipse cx="177" cy="154" rx="28" ry="33" fill="#dfb889"/><path d="M148 156L141 135L154 112Q184 96 208 126L207 154L195 133L165 137Z" fill="#244849"/><path d="M146 126Q177 109 208 128M146 139Q177 123 209 140" fill="none" stroke="#b3c0a3" stroke-width="3"/><path d="M183 153L193 154M191 168L204 170" stroke="#40584c" stroke-width="2"/><path d="M204 172L294 142L302 158L208 179Z" fill="#b9864d"/><path d="M292 144L327 111L347 169L300 157Z" fill="#d5a45d"/><ellipse cx="337" cy="140" rx="9" ry="31" transform="rotate(-18 337 140)" fill="#8b7145"/><path d="M226 166L271 151" stroke="#ead19a" stroke-width="3"/><path d="M111 306Q177 325 247 307" stroke="#9ebba6" stroke-width="3" fill="none"/><path d="M338 139Q379 92 387 143T399 204M332 123Q359 61 397 73" class="ribbon"/></g>`}
const paths=[[[68,225],[102,201],[139,209],[173,168],[206,184],[238,139],[275,156],[310,115],[335,135]],[[45,272],[78,247],[107,257],[139,237],[168,247],[206,220],[237,219],[243,142],[253,138],[254,100],[265,99],[265,76],[287,76],[288,99],[300,101],[309,139],[319,142],[330,232]],[[200,66],[230,106],[267,102],[254,145],[290,176],[248,191],[247,234],[207,218],[175,249],[156,207],[114,204],[134,165],[113,128],[158,125],[170,86],[200,66]],[[201,99],[226,122],[221,158],[250,197],[281,155],[296,163],[255,222],[228,207],[237,266],[214,282],[244,322],[234,337],[198,280],[172,341],[145,333],[165,274],[165,253],[177,205],[147,233],[101,184]],[[205,173],[256,155],[293,143],[327,112],[347,168],[301,158],[253,174],[210,181]]];
function cutScene(){const i=state.chapter;const points=paths[i],p=points.map(q=>q.join(',')).join(' ');let base=i===0?`<path d="M44 85L309 54L361 283L87 315Z" fill="#6e9d8e"/><path d="M44 85L205 180L309 54L212 300L87 315Z" fill="#b5c5a6"/><path d="M205 180L309 54L361 283Z" fill="#d7a36d"/>`:i===1?tower():i===2?flower(200,175,.85):i===3?dancer():musician();return svg(`<g opacity=".7">${base}</g><path d="M25 53L362 42L380 310L41 331Z" fill="${i===2?'#e7c5a0':'#d0a36a'}" opacity=".94" filter="url(#grain)"/><path d="M40 57L200 183L364 44M200 183L47 325" stroke="#f6e5c7" stroke-width="1" opacity=".6"/><polyline class="cut-path" points="${p}"/><polyline id="cutDone" class="cut-done" points="${points.slice(0,state.cut+1).map(q=>q.join(',')).join(' ')}"/><circle id="cutMarker" class="cut-marker" cx="${points[state.cut][0]}" cy="${points[state.cut][1]}" r="10"/><text x="200" y="351" text-anchor="middle" fill="#6a7768" font-size="10" letter-spacing="3">沿着纸痕 · 慢慢剪开</text>`)}
function scene(){const i=state.chapter;if(state.phase==='cut')return cutScene();if(i===0)return svg(`<g class="${state.folded?'fold-paper':''}"><path d="M39 100L303 59L361 281L94 319Z" fill="#eee0c2"/>${state.folded?`<path d="M64 239L110 176L158 210L218 136L279 186L328 150L350 275L98 304Z" fill="#8fae99"/><path d="M83 267L154 214L193 250L269 190L349 270L98 304Z" fill="#377778"/><path d="M110 295Q216 236 278 270T341 288" fill="none" stroke="#d3e6d2" stroke-width="18"/>`:`<path d="M39 100L203 190L303 59L94 319Z" fill="#b1c4a7"/><path d="M203 190L303 59L361 281Z" fill="#cba174"/><path d="M203 190L94 319L361 281Z" fill="#4c8580"/><path d="M203 190L303 59" stroke="#fff1cb"/>`}</g>`);if(i===1)return svg(tower());if(i===2)return svg(`${cave()}${state.phase==='drag'?`<circle class="drop-target" cx="102" cy="205" r="41"/>`+`<g id="piece" class="draggable" role="button" aria-label="窗花纸片" tabindex="0">${flower(245,80,.35,['#cc6045','#b34f42','#d27c4b'][state.pattern])}</g>`:state.phase==='done'?flower(102,205,.31,['#cc6045','#b34f42','#d27c4b'][state.pattern]):''}`);if(i===3)return svg(`${dancer()}${state.phase==='drag'?`<rect class="drop-target" x="260" y="125" width="58" height="65" rx="20"/><g id="piece" class="draggable" role="button" aria-label="彩绸纸片" tabindex="0"><path d="M74 78Q121 25 131 80T173 91" fill="none" stroke="#cc6647" stroke-width="15"/></g>`:''}`);return svg(musician())}
function render(){const i=state.chapter,c=chapters[i],done=state.phase==='done';app.innerHTML=`<section class="screen">${top()}<div class="progress">${Array.from({length:6},(_,n)=>`<span class="${n===i?'on':''}"></span>`).join('')}</div><div class="chapter-head"><span class="eyebrow">${c.label} · ${['初见','守望','烟火','欢腾','回响'][i]}</span><h1>${c.title}</h1><p>— ${c.sub} —</p></div><div class="scene ${state.phase==='cut'?'cutboard':''}" id="scene"><div class="scene-bg"></div>${scene()}</div><div class="narrative">${(done?c.after:c.story).replace('\n','<br>')}</div><div class="controls" id="controls">${controlContent()}</div></section>`;bindTop();bindControls();if(state.phase==='cut')bindCut();if(state.phase==='drag')bindDrag();}
function controlContent(){let i=state.chapter,p=state.phase;if(p==='intro')return `<div class="hint">${i===0?'轻轻展开一角，唤醒纸里的山河':'下一段故事，等你亲手剪开'}</div><button class="primary" id="action">${i===0?'展开这张纸':'开始剪刻'}<b>→</b></button><div class="utility"><button id="knowledge">文化拾遗</button><button id="read">听旁白 ♪</button></div>`;if(p==='unfold')return `<div class="hint">纸已展开 · 第一条山脊正在等你</div><button class="primary" id="action">学习剪刻<b>✂</b></button>`;if(p==='cut')return `<div class="hint" id="cutHint">按住圆点，沿虚线向前滑动 · 0%</div><div class="utility"><button id="retry">重新剪刻 ↺</button><button id="assist">辅助剪刻</button></div><div class="small-label">也可用方向键逐点剪刻</div>`;if(p==='drag')return `<div class="hint">${i===2?'把上方窗花拖进左侧窗框':'把上方彩绸拖到舞者右手的虚框'}<br>也可点选纸片，再点击虚框</div>${i===2?`<div class="utility"><button id="pattern">切换窗花配色 ↻</button></div>`:''}<div class="utility"><button id="retry">重新开始 ↺</button></div>`;if(p==='rhythm')return `<div class="hint" id="rhythmHint">跟随鼓点 · 亮起时点击 · 完成 4 拍</div><div class="beats">${Array.from({length:4},(_,n)=>`<i class="beat-dot ${n<state.beats?'hit':''}"></i>`).join('')}</div><button class="drum" id="drum" aria-label="点击鼓点">咚</button><div class="utility"><button id="retry">重试</button><button id="assist">辅助跟拍</button></div>`;if(p==='sound')return `<div class="hint">点亮三个音符，让纸带随声音飘起来</div><div class="notes">${['风','山','河'].map((x,n)=>`<button class="note" data-note="${n}">${x}</button>`).join('')}</div><div class="small-label">交互合成音色 · 非传统曲目实录</div>`;return `<div class="collected">${i?'文化纹样已收入长卷':'第一道山河纸痕 · 已完成'}</div><button class="primary" id="action">${i===4?'展开我的榆林':'继续 · '+chapters[i+1].title}<b>→</b></button><div class="utility"><button id="knowledge">文化拾遗 ↗</button><button id="retry">再剪一次 ↺</button><button id="read">听旁白 ♪</button></div>`}
function bindControls(){const a=$('#action');if(a)a.onclick=()=>{if(state.phase==='done')return enter(state.chapter+1);if(state.chapter===0&&state.phase==='intro'){state.folded=true;state.phase='unfold';render();return}state.phase='cut';state.cut=0;render()};if($('#retry'))$('#retry').onclick=()=>enter(state.chapter);if($('#knowledge'))$('#knowledge').onclick=()=>card(state.chapter);if($('#read'))$('#read').onclick=readAloud;if($('#assist'))$('#assist').onclick=()=>{if(state.phase==='cut'){const token=run;function step(){if(token!==run||state.phase!=='cut')return;advanceCut();if(state.phase==='cut')later(step,100)}step()}else{state.beats=4;finish()}};if($('#pattern'))$('#pattern').onclick=()=>{state.pattern=(state.pattern+1)%3;render()};if($('#drum'))startRhythm();document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{let n=+b.dataset.note;tone([392,440,523.25][n],.55,'sawtooth');if(!state.placed.includes(n))state.placed.push(n);b.style.background='#b6c9ac';$('#scene').classList.add('playing');later(()=>$('#scene')?.classList.remove('playing'),700);if(state.placed.length===3)later(finish,800);else toast(`${state.placed.length}/3 · 纸带接住了声音${state.sound?'':'（声音已关闭）'}`)})}
function readAloud(){if(!state.sound){toast('请先点右上角开启声音');return}if(!('speechSynthesis'in window)){toast('当前浏览器不支持旁白朗读');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(state.phase==='done'?chapters[state.chapter].after:chapters[state.chapter].story);u.lang='zh-CN';u.rate=.85;speechSynthesis.speak(u)}
function bindCut(){const el=$('#scene'),s=el.querySelector('svg');el.tabIndex=0;el.setAttribute('aria-label','沿圆点剪刻，触摸滑动或使用方向键');let down=false;const move=e=>{if(!down||state.phase!=='cut')return;const pt=s.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const q=pt.matrixTransform(s.getScreenCTM().inverse());let target=paths[state.chapter][state.cut];if(Math.hypot(q.x-target[0],q.y-target[1])<30)advanceCut()};el.onpointerdown=e=>{down=true;el.setPointerCapture(e.pointerId);move(e)};el.onpointermove=move;el.onpointerup=()=>down=false;el.onpointercancel=()=>down=false;el.onkeydown=e=>{if(['ArrowRight','ArrowDown','Enter',' '].includes(e.key)){e.preventDefault();advanceCut()}};}
function advanceCut(){const p=paths[state.chapter];if(state.cut>=p.length-1)return reveal();state.cut++;$('#cutDone').setAttribute('points',p.slice(0,state.cut+1).map(q=>q.join(',')).join(' '));$('#cutMarker').setAttribute('cx',p[state.cut][0]);$('#cutMarker').setAttribute('cy',p[state.cut][1]);$('#cutHint').textContent=`顺着纸痕继续 · ${Math.round(state.cut/(p.length-1)*100)}%`;if(navigator.vibrate)navigator.vibrate(8);if(state.cut===p.length-1)later(reveal,220)}
function reveal(){if(state.phase!=='cut')return;state.phase='reveal';render();$('#scene svg').classList.add('fold-paper');$('#controls').innerHTML='<div class="hint">轻轻展开，纸上的故事醒来了…</div><button class="quiet" id="skip">跳过展开动画 →</button>';let token=run;const next=()=>{if(token!==run||state.phase!=='reveal')return;state.phase=state.chapter===2||state.chapter===3?'drag':state.chapter===4?'sound':'done';if(state.phase==='done')return finish();render()};$('#skip').onclick=next;later(next,1200)}
function bindDrag(){const sceneEl=$('#scene'),s=sceneEl.querySelector('svg'),piece=$('#piece'),target=s.querySelector('.drop-target');let selected=false,active=false,origin=null;const pos=e=>{let p=s.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(s.getScreenCTM().inverse())};function settle(){active=false;piece.setAttribute('transform','');selected=false;toast('再靠近一点，纸片会自动贴合')};function drop(){if(state.chapter===3){state.phase='rhythm';state.beats=0;render()}else finish()};piece.onpointerdown=e=>{active=true;origin=pos(e);piece.setPointerCapture(e.pointerId);e.stopPropagation()};piece.onpointermove=e=>{if(!active)return;let p=pos(e);piece.setAttribute('transform',`translate(${p.x-origin.x} ${p.y-origin.y})`)};piece.onpointerup=e=>{let p=pos(e),t=state.chapter===2?[102,205]:[289,157];active=false;if(Math.hypot(p.x-t[0],p.y-t[1])<65)drop();else if(Math.hypot(p.x-origin.x,p.y-origin.y)<12){selected=true;toast('已选中纸片 · 点击虚线轮廓')}else settle()};piece.onpointercancel=settle;piece.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){selected=true;toast('已选中 · 点虚框或再按回车贴合');piece.onkeydown=e2=>{if(e2.key==='Enter')drop()}}};target.onclick=()=>{if(selected)drop();else toast('先点选上方纸片')};}
let beatStart=0;
function startRhythm(){beatStart=performance.now();const token=run;function tick(){if(token!==run||state.phase!=='rhythm')return;tone(110,.12,'triangle');later(tick,700)}tick();$('#drum').onclick=()=>{const delta=(performance.now()-beatStart)%700;if(delta<250||delta>490){state.beats++;tone(140,.12,'triangle');document.querySelectorAll('.beat-dot')[state.beats-1]?.classList.add('hit');$('#rhythmHint').textContent=`踩上鼓点了 · ${state.beats} / 4 拍`;if(state.beats>=4)finish()}else{$('#rhythmHint').textContent='别急，等下一次鼓点亮起再点';tone(80,.08,'triangle')}}}
function tone(freq,duration=.3,type='sine'){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain(),f=audio.createBiquadFilter();o.type=type;o.frequency.value=freq;f.type='lowpass';f.frequency.value=1800;g.gain.setValueAtTime(0,audio.currentTime);g.gain.linearRampToValueAtTime(.12,audio.currentTime+.025);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(f);f.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration+.05)}catch{toast('当前浏览器无法播放音频')}}
function finish(){clearWork();state.phase='done';if(!saved.completed.includes(state.chapter))saved.completed.push(state.chapter);saved.completed.sort((a,b)=>a-b);saved.chapter=Math.min(state.chapter+1,5);save();render();tone(523,.3);}
function ending(){app.innerHTML=`<section class="screen">${top()}<div class="progress">${Array.from({length:6},(_,i)=>`<span class="${i===5?'on':''}"></span>`).join('')}</div><div class="chapter-head"><span class="eyebrow">终章 · 一纸一城</span><h1>展开榆林</h1><p>把一路遇见，拼成心里的山河</p></div><div class="scene finish-scene"><div class="scene-bg"></div><svg viewBox="0 0 400 280" aria-label="长卷拼合位置">${[[55,195],[150,215],[245,210],[345,195]].map((p,i)=>`<g class="end-slot" data-slot="${i}"><circle cx="${p[0]}" cy="${p[1]}" r="33" fill="#f6eedacc" stroke="#a36d47" stroke-dasharray="4 5"/><text x="${p[0]}" y="${p[1]+5}" text-anchor="middle" font-size="14" fill="#7b674a">${['塞','家','舞','音'][i]}</text></g>`).join('')}</svg></div><div class="narrative" id="endStory">四枚纹样，四段相逢。<br>将它们安放在长卷上，让榆林完整展开。</div><div class="collection">${['▥','❋','舞','♪'].map((x,i)=>`<button data-piece="${i}" aria-label="拼合${['边塞','窗花','秧歌','唢呐'][i]}纹样">${x}</button>`).join('')}</div><div class="controls"><div class="hint" id="endHint">拖入对应圆框，或点选纹样后点圆框</div><label class="small-label" for="owner">给这幅山河，留一个名字</label><input class="name-input" id="owner" placeholder="我的榆林故事" maxlength="16" value=""><button class="primary" id="poster" disabled style="opacity:.45">生成我的剪纸海报<b>↗</b></button><div class="utility"><button id="scroll">保存横版长卷</button><button id="restart">重温故事 ↺</button></div></div></section>`;bindTop();$('#owner').value=saved.name||'';$('#owner').oninput=e=>{saved.name=e.target.value;save()};let selected=null;const slots=document.querySelectorAll('.end-slot');const place=i=>{if(!state.placed.includes(i))state.placed.push(i);const b=$(`[data-piece="${i}"]`);b.classList.add('placed');b.textContent='✓';let t=$(`[data-slot="${i}"] text`);t.textContent=['▥','❋','舞','♪'][i];t.setAttribute('fill','#a94f3e');t.setAttribute('font-size','26');if(state.placed.length===4){$('#endHint').textContent='长卷已展开 · 山河与烟火，都在这一纸';$('#poster').disabled=false;$('#poster').style.opacity=1;if(!saved.completed.includes(5))saved.completed.push(5);save()}};document.querySelectorAll('[data-piece]').forEach(b=>{const i=+b.dataset.piece;let moved=false;b.onpointerdown=e=>{moved=false;b.setPointerCapture(e.pointerId);selected=i};b.onpointermove=e=>{if(e.buttons){moved=true;b.style.transform=`translateY(-25px)`}};b.onpointerup=e=>{b.style.transform='';if(moved){let slot=slots[i].querySelector('circle').getBoundingClientRect();if(e.clientX>slot.left-30&&e.clientX<slot.right+30&&e.clientY>slot.top-30&&e.clientY<slot.bottom+30)place(i);else toast('拖到相同故事的圆框里')}else toast('已选中 · 点击对应的长卷圆框')};b.onclick=()=>selected=i;b.onkeydown=e=>{if(e.key==='Enter'){selected=i;toast('已选中纹样')}}});slots.forEach((s,i)=>{s.setAttribute('tabindex','0');s.setAttribute('role','button');s.setAttribute('aria-label','放入'+['边塞','窗花','秧歌','唢呐'][i]+'纹样');s.onclick=()=>{if(selected===i)place(i);else toast('选一枚与这处故事相同的纹样')};s.onkeydown=e=>{if(e.key==='Enter'&&selected===i)place(i)}});$('#poster').onclick=()=>exportArt(false);$('#scroll').onclick=()=>state.placed.length===4?exportArt(true):toast('先把四枚纹样拼进长卷');$('#restart').onclick=()=>enter(0);}
async function exportArt(wide){toast('正在装裱你的榆林…');const canvas=document.createElement('canvas');canvas.width=wide?1800:1080;canvas.height=wide?900:1700;let ctx=canvas.getContext('2d');ctx.fillStyle='#f7efdf';ctx.fillRect(0,0,canvas.width,canvas.height);const im=new Image();im.src='landscape.png';try{await im.decode();ctx.drawImage(im,0,wide?0:270,canvas.width,wide?800:1120)}catch{}ctx.fillStyle='#f7efdf';ctx.fillRect(0,0,canvas.width,wide?150:290);ctx.fillStyle='#184c4b';ctx.textAlign='center';ctx.font=`bold ${wide?74:112}px KaiTi,serif`;ctx.fillText('一纸榆林',canvas.width/2,wide?97:160);ctx.font='24px serif';ctx.fillText('一 剪 一 景  ·  一 纸 一 城',canvas.width/2,wide?133:227);const y=wide?750:1300;ctx.fillStyle='#f7efdfec';ctx.fillRect(0,y,canvas.width,canvas.height-y);ctx.font='28px serif';ctx.fillStyle='#9e503e';ctx.fillText('边塞  ·  人家  ·  红火  ·  声音',canvas.width/2,y+68);ctx.fillStyle='#214e49';ctx.font='36px serif';ctx.fillText((saved.name||'我的榆林故事').slice(0,16),canvas.width/2,y+135);ctx.font='22px serif';ctx.fillText('我用一张纸，收藏了一座城。',canvas.width/2,y+186);if(!wide){ctx.font='18px sans-serif';ctx.fillText('清爽榆林 · 指尖上的文化行旅',canvas.width/2,1600)}const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)return toast('生成失败，请重试');const url=URL.createObjectURL(blob);show(`<span class="card-overline">YOUR YULIN · 收藏这一纸</span><h2>${wide?'山河长卷':'我的榆林故事'}</h2><img class="poster-preview" alt="个人榆林剪纸海报" src="${url}"><p>长按图片保存，或使用下方按钮。分享将由你在系统面板中选择对象。</p><button class="primary" id="download">保存图片 ↓</button><button class="quiet" id="share">分享图片 ↗</button>`);$('#download').onclick=()=>{const a=document.createElement('a');a.href=url;a.download=wide?'一纸榆林-山河长卷.png':'一纸榆林-我的剪纸海报.png';a.click()};$('#share').onclick=async()=>{const f=new File([blob],'一纸榆林.png',{type:'image/png'});try{if(navigator.canShare?.({files:[f]}))await navigator.share({files:[f],title:'一纸榆林'});else toast('当前浏览器不支持图片分享，请保存后分享')}catch(e){if(e.name!=='AbortError')toast('分享未完成，可先保存图片')}};}
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(audio)audio.suspend();if('speechSynthesis'in window)speechSynthesis.cancel()}});
cover();
